public void onSendFailed(MailReportJob job, String subject, String html, Exception e) {
    MailDeadLetter letter = new MailDeadLetter();
    letter.setJobId(job.getId());
    letter.setBusinessDate(businessDate);
    // 存已经渲染好的成品：重试时不再查库、不再渲染
    letter.setSubject(subject);
    letter.setContent(html);
    letter.setRecipients(JSON.toJSONString(recipients));
    letter.setStatus(STATUS_PENDING);
    letter.setRetryCount(0);
    letter.setNextRetryAt(new Date(System.currentTimeMillis() + FIRST_RETRY_1MIN));
    letter.setErrorMsg(shorten(e.getMessage()));
    deadLetterDao.insert(letter);
    log.error("mail send failed, saved to dead letter. jobId: {}, letterId: {}",
            job.getId(), letter.getId(), e);
}

public void scan() {
    // 每轮最多捞 50 条，避免一次把所有积压都拉进内存
    List<MailDeadLetter> letters = deadLetterDao.queryPending(new Date(), SCAN_LIMIT_50);
    for (MailDeadLetter letter : letters) {
        // 抢 10 秒短锁：两个通道同时扫到同一条时只有一个能处理
        String lockKey = "sendmail:dl:" + letter.getId();
        Boolean locked = redis.opsForValue().setIfAbsent(lockKey, "1", Duration.ofSeconds(10));
        if (!Boolean.TRUE.equals(locked)) {
            continue;
        }
        try {
            int count = letter.getRetryCount();
            if (count >= MAX_RETRY_20) {
                markGiveUp(letter);
                continue;
            }
            sendSnapshot(letter);
            markSent(letter);
        } catch (Exception e) {
            int next = letter.getRetryCount() + 1;
            markRetry(letter, next, nextRetryAt(next));   // 1/5/30/120/720 分钟后每 1440 分钟
        }
    }
}
